code_example:
typedef void (*copy_func_t)(void *dest, const void *src);

struct Panda {
    char *name;
};

void panda_copy(void *dest, const void *src) {
    struct Panda *d = (struct Panda *)dest;
    const struct Panda *s = (const struct Panda *)src;
    d->name = strdup(s->name); // Deep copy of string
}

struct Panda ying_yang = { .name = "ying_yang" };
struct Panda copy_of_ying_yang;
copy_of_ying_yang.copy = panda_copy;
copy_of_ying_yang.copy(&copy_of_ying_yang, &ying_yang);
